package app

func sandboxAgentTools() []builtinToolDefinition {
	return []builtinToolDefinition{
		{"read_file", "读取文件", "Read UTF-8 text in the sandbox. Paths are relative to the session CWD or absolute under /data; parent traversal is rejected. The result is bounded and reports a byte offset for continuing. Use read_image for images.", "read_only", `{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":1024},"offset":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":1,"maximum":32768}},"required":["path"],"additionalProperties":false}`},
		{"read_image", "读取图片", "Read a PNG, JPEG or WebP file as native model vision input when the session model supports images. This reads a private snapshot into model history; use present to explicitly retain a deliverable. Paths are relative to CWD or absolute under /data.", "read_only", `{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":1024}},"required":["path"],"additionalProperties":false}`},
		{"write_file", "写入文件", "Write UTF-8 text to a sandbox file, up to 32768 UTF-8 bytes. Parent directories must exist. Existing files require overwrite=true; provide the last read identity to detect changes. Skill directories are read-only through this tool. Paths are relative to CWD or under /data.", "side_effect", `{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":1024},"content":{"type":"string","maxLength":32768},"overwrite":{"type":"boolean"},"identity":{"type":"string","pattern":"^[a-f0-9]{64}$"}},"required":["path","content"],"additionalProperties":false}`},
		{"edit_file", "编辑文件", "Replace exactly one occurrence of old_text in a bounded UTF-8 file. Ambiguous matches fail without changing the file. Paths are relative to CWD or under /data; platform skill files are protected.", "side_effect", `{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":1024},"old_text":{"type":"string","minLength":1,"maxLength":8192},"new_text":{"type":"string","maxLength":16384}},"required":["path","old_text","new_text"],"additionalProperties":false}`},
		{"glob", "查找文件", "Find file paths using a slash-aware glob pattern below a sandbox directory. Searches are bounded and skip symbolic links and internal state. Paths are relative to CWD or under /data.", "read_only", `{"type":"object","properties":{"path":{"type":"string","maxLength":1024},"pattern":{"type":"string","minLength":1,"maxLength":1024},"limit":{"type":"integer","minimum":1,"maximum":200}},"required":["pattern"],"additionalProperties":false}`},
		{"grep", "搜索文件内容", "Find text in bounded UTF-8 files below a sandbox directory. The pattern is a Go regular expression unless literal=true. Searches skip symbolic links and private helper state. Paths are relative to CWD or under /data.", "read_only", `{"type":"object","properties":{"path":{"type":"string","maxLength":1024},"pattern":{"type":"string","minLength":1,"maxLength":1024},"literal":{"type":"boolean"},"case_sensitive":{"type":"boolean"},"limit":{"type":"integer","minimum":1,"maximum":200}},"required":["pattern"],"additionalProperties":false}`},
		{"import_file", "导入文件", "Copy an attachment or artifact explicitly selected in the current root input into the session CWD. This creates a working copy without overwriting existing files. Do not guess file IDs from other conversations.", "side_effect", `{"type":"object","properties":{"source":{"type":"object","properties":{"kind":{"type":"string","enum":["attachment","artifact"]},"id":{"type":"string","pattern":"^[1-9][0-9]*$"}},"required":["kind","id"],"additionalProperties":false},"destination":{"type":"string","minLength":1,"maxLength":1024}},"required":["source","destination"],"additionalProperties":false}`},
		{"exec_command", "执行命令", "Run a shell command as the sandbox workload user in this session CWD. Commands share files, dependencies and ports with other sessions. Use background=true for longer work, then process_status/output/cancel. Returned execution_id is a platform ID, not a PID. Secrets and external-service authorization are not granted by shell access.", "side_effect", `{"type":"object","properties":{"command":{"type":"string","minLength":1,"maxLength":32768},"background":{"type":"boolean"},"timeout_seconds":{"type":"integer","minimum":1,"maximum":600},"max_output_bytes":{"type":"integer","minimum":4,"maximum":65536}},"required":["command"],"additionalProperties":false}`},
		{"process_status", "查询进程", "Inspect a command execution from this root run. Only a verified exit is completion; outcome_unknown must be reconciled before repeating side effects.", "read_only", `{"type":"object","properties":{"execution_id":{"type":"string","pattern":"^[1-9][0-9]*$"}},"required":["execution_id"],"additionalProperties":false}`},
		{"process_output", "读取进程输出", "Read bounded output from a command in this root run. Pass the returned cursor to continue; background output may merge stdout and stderr.", "read_only", `{"type":"object","properties":{"execution_id":{"type":"string","pattern":"^[1-9][0-9]*$"},"cursor":{"type":"string","maxLength":4096},"max_output_bytes":{"type":"integer","minimum":4,"maximum":65536}},"required":["execution_id"],"additionalProperties":false}`},
		{"process_cancel", "取消进程", "Request cancellation of a command in this root run. A cancellation acknowledgement does not by itself prove the process has stopped; inspect the returned state.", "side_effect", `{"type":"object","properties":{"execution_id":{"type":"string","pattern":"^[1-9][0-9]*$"}},"required":["execution_id"],"additionalProperties":false}`},
		{"present", "保存产物", "Explicitly retain verified snapshots of deliverable files from this session CWD. Use when the user should be able to download a final report or output after sandbox cleanup. Working files alone are not retained artifacts. Up to 20 files, 100 MiB each and 200 MiB total.", "side_effect", `{"type":"object","properties":{"files":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":1024},"description":{"type":"string","maxLength":2000}},"required":["path"],"additionalProperties":false}}},"required":["files"],"additionalProperties":false}`},
	}
}

func isSandboxAgentTool(key string) bool {
	for _, definition := range sandboxAgentTools() {
		if definition.key == key {
			return true
		}
	}
	return false
}
